528	    impl Read for ChunkedReader<'_> {
529	        fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
530	            if self.pos == self.data.len() {
531	                return Ok(0);
532	            }
533	            let mut limit = buf.len();
534	            if !self.chunk_sizes.is_empty() {
535	                limit = limit.min(self.chunk_sizes[self.chunk_index % self.chunk_sizes.len()]);
536	                self.chunk_index += 1;
537	            }
538	            let n = limit.min(self.data.len() - self.pos);
539	            buf[..n].copy_from_slice(&self.data[self.pos..self.pos + n]);
540	            self.pos += n;
541	            Ok(n)
542	        }
543	    }
