596	    /// 按脚本驱动的读取器：每个步骤要么返回下一段内容（长度可短于缓冲区），
597	    /// 要么返回一个错误。脚本用完后继续返回剩余内容，内容耗尽后返回 Ok(0)。
598	    /// 用于精确模拟“中断出现在任意位置”的读取序列。
599	    enum Step {
600	        /// 返回下一段内容（可为空切片以外的任意长度）。
601	        Data,
602	        /// 返回指定错误。
603	        Fail(io::ErrorKind, &'static str),
604	    }
605	
606	    struct ScriptedReader<'a> {
607	        data: &'a [u8],
608	        pos: usize,
609	        steps: &'a [Step],
610	        step_index: usize,
611	    }
612	
613	    impl<'a> ScriptedReader<'a> {
614	        fn new(data: &'a [u8], steps: &'a [Step]) -> Self {
615	            ScriptedReader { data, pos: 0, steps, step_index: 0 }
616	        }
617	    }
618	
619	    impl Read for ScriptedReader<'_> {
620	        fn read(&mut self, buf: &mut [u8]) -> io::Result<usize> {
621	            match self.steps.get(self.step_index) {
622	                Some(Step::Data) => {
623	                    self.step_index += 1;
624	                    // 每段最多给剩余内容的一半，保证一段脚本可能对应多次内容返回，
625	                    // 且片段长度通常短于缓冲区容量。
626	                    let remaining = self.data.len() - self.pos;
627	                    let n = (remaining / 2).max(1).min(remaining).min(buf.len());
628	                    buf[..n].copy_from_slice(&self.data[self.pos..self.pos + n]);
629	                    self.pos += n;
630	                    Ok(n)
631	                }
632	                Some(Step::Fail(kind, msg)) => {
633	                    self.step_index += 1;
634	                    Err(io::Error::new(*kind, *msg))
635	                }
636	                None => {
637	                    let remaining = self.data.len() - self.pos;
638	                    let n = remaining.min(buf.len());
639	                    buf[..n].copy_from_slice(&self.data[self.pos..self.pos + n]);
640	                    self.pos += n;
641	                    Ok(n)
642	                }
643	            }
644	        }
645	    }
