            Ed25519PublicKey::from_spki_der(&der).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
        // 公钥 33 字节。
        let mut der = spki_der(&[0x2b, 0x65, 0x70], &[0x22; 32]);
        der[1] = 0x2b;
        der[10] = 0x22;
        der.push(0x00);
        assert_eq!(
            Ed25519PublicKey::from_spki_der(&der).unwrap_err(),
            ImportPublicKeyError::Malformed
        );
    }

