180	/// 把成功结果一次性完整写到标准输出并立即刷出，返回进程退出码。
181	///
182	/// 成功的含义是**整行结果（含末尾换行）已经真正交到输出端**：仅算出
183	/// 摘要或通过比较并不构成成功，写中途失败或最后的刷新失败（例如标准
184	/// 输出被重定向到只读位置，或管道接收方提前关闭）都必须以退出码 1
185	/// 结束，而不是让 `println!` 的 panic 打印崩溃信息，也不能照常报成功。
186	///
187	/// 输出失败时只在标准错误给出一条以 `inkseal:` 开头的单行提示，保留
188	/// 系统给出的具体原因；不补充用法说明，不把摘要改写到标准错误，也不
189	/// 重试整行输出。标准输出此前可能已经收到结果的前几个字节，这些字节
190	/// 无法也不必撤回。若连这条提示都写不出去，同样静默地以退出码 1
191	/// 结束——报告输出失败的过程自身绝不能再崩溃。
192	fn emit_success(line: &[u8]) -> ExitCode {
193	    match write_stdout_all(line) {
194	        Ok(()) => ExitCode::SUCCESS,
195	        Err(err) => {
196	            // 与失败路径同一条规则：提示本身写不出去也忽略，只需保证
197	            // 退出码为 1，绝不经过会因写失败而 panic 的宏。
198	            let hint = format!("inkseal: unable to write to standard output: {err}\n");
199	            let _ = write_stderr_all(hint.as_bytes());
200	            ExitCode::FAILURE
201	        }
202	    }
203	}
204	
205	/// 失败路径的统一出口：把既有的错误提示（原始字节，含其行结构）尽力
206	/// 写到标准错误，然后以约定的退出码（用法错误 `2`、其余失败 `1`）结束。
207	///
208	/// 提示说明的是**已经发生的失败**：接收方是否还读得到提示，不能改变
209	/// 命令对本次操作的判断。标准错误被接到另一个程序而接收方提前关闭管道、
210	/// 或从一开始就拒绝写入时，`eprintln!` 会在 EPIPE/EBADF 上 panic，使
211	/// 进程以崩溃退出码（101）结束并打出崩溃信息，丢掉原本约定的退出码。
212	/// 这里与 [emit_success] 一样直接走 `write` 系统调用并忽略写失败：
213	/// 已经送出的字节保留，写不出去的部分不补齐、不重试、不改写到标准输出，
214	/// 只保证静默地以 `code` 正常结束。
215	fn emit_error(code: u8, message: &[u8]) -> ExitCode {
216	    let _ = write_stderr_all(message);
217	    ExitCode::from(code)
218	}
219	
220	/// 把 `data` 完整写到给定输出端：成功结果与失败提示共用的唯一交付规则。
221	///
222	/// 只要输出端仍可继续接收，临时中断（EINTR）原地重试、一次只接收部分
223	/// 字节（短写）就续写剩余部分，直到全部字节交付完毕——最终内容完整、
224	/// 顺序不变且没有重复。真正的写入错误结束本次交付并返回该错误；对正数
225	/// 计数的 write 返回 0 没有任何进展，按失败处理而不是空转。`target`
226	/// 只用于“毫无进展”这条合成错误的文字，系统给出的真实错误原样返回。
227	#[cfg(unix)]
228	fn write_fd_all(fd: std::os::fd::RawFd, mut data: &[u8], target: &'static str) -> io::Result<()> {
229	    use std::os::raw::c_void;
230	
231	    unsafe extern "C" {
232	        fn write(fd: std::os::fd::RawFd, buf: *const c_void, count: usize) -> isize;
233	    }
234	
235	    while !data.is_empty() {
236	        let written = unsafe { write(fd, data.as_ptr().cast::<c_void>(), data.len()) };
237	        if written < 0 {
238	            let err = io::Error::last_os_error();
239	            // 临时中断不代表任何字节的命运，原地重试。
240	            if err.kind() == io::ErrorKind::Interrupted {
241	                continue;
242	            }
243	            return Err(err);
244	        }
245	        let n = written as usize;
246	        if n == 0 {
247	            // 对正数计数的 write 返回 0 没有可恢复的含义，停止续写，
248	            // 避免在此空转。
249	            return Err(io::Error::new(
250	                io::ErrorKind::WriteZero,
251	                format!("write to {target} returned no progress"),
252	            ));
253	        }
254	        data = &data[n..];
255	    }
256	    Ok(())
257	}
258	
259	/// 非 Unix 目标：标准库句柄不存在上述特殊处理，沿用加锁写入并显式刷新。
260	/// `write_all` 内部已处理短写与 EINTR，语义与 Unix 路径一致。
261	#[cfg(not(unix))]
262	fn write_locked_all(mut handle: impl std::io::Write, data: &[u8]) -> io::Result<()> {
263	    use std::io::Write;
264	
265	    handle.write_all(data)?;
266	    handle.flush()
267	}
268	
269	/// 直接对标准输出的原始文件描述符发起 `write`，绕过标准库 `Stdout`
270	/// 对“输出端不存在/拒绝写入”这类失败的特殊处理——它在某些情况下会把
271	/// 失败（如 fd 以只读方式打开时内核返回的 EBADF）静默报告为成功，导致
272	/// 调用方误以为结果已交付。
273	#[cfg(unix)]
274	fn write_stdout_all(line: &[u8]) -> io::Result<()> {
275	    const STDOUT_FD: std::os::fd::RawFd = 1;
276	    write_fd_all(STDOUT_FD, line, "standard output")
277	}
278	
279	/// 非 Unix 目标：标准库句柄不存在上述特殊处理，沿用加锁写入并显式刷新。
280	#[cfg(not(unix))]
281	fn write_stdout_all(line: &[u8]) -> io::Result<()> {
282	    write_locked_all(io::stdout().lock(), line)
283	}
284	
285	/// 直接对标准错误的原始文件描述符发起 `write`，绕过标准库 `Stderr`
286	/// 的行缓冲以及 `eprintln!`/`writeln!` 在写失败时的 panic（宏内部
287	/// `unwrap`）。任何无法继续写入的错误都返回，由调用方决定忽略——
288	/// 失败提示本身绝不能再崩溃。
289	#[cfg(unix)]
290	fn write_stderr_all(message: &[u8]) -> io::Result<()> {
291	    const STDERR_FD: std::os::fd::RawFd = 2;
292	    write_fd_all(STDERR_FD, message, "standard error")
293	}
294	
295	/// 非 Unix 目标：沿用加锁写入并显式刷新；写失败同样由调用方忽略。
296	#[cfg(not(unix))]
297	fn write_stderr_all(message: &[u8]) -> io::Result<()> {
298	    write_locked_all(io::stderr().lock(), message)
299	}
