369	/// 读取并解析摘要文件时的失败。
370	///
371	/// [`Access`](Self::Access) 是摘要文件本身的访问问题（打不开或读取中途
372	/// 失败，以 `1` 退出），直接复用三条命令共用的 [`FileAccessError`]——它
373	/// 已带 [`FileRole::DigestFile`]，因此提示会明确对象是摘要文件，又与内容
374	/// 文件遵循同一条打开/读取分类规则。[`Malformed`](Self::Malformed) 是内容
375	/// 不符合“恰好一份摘要”的格式约定（以 `2` 退出）。两类都必须在待核对
376	/// 文件被访问之前判定，且提示里都要带上摘要文件自己的路径，绝不能把摘要
377	/// 文件的问题改报成待核对文件的访问错误。
378	enum DigestFileError {
379	    /// 摘要文件无法打开或读取中途失败（含路径指向目录时的读取错误）。
380	    Access(FileAccessError),
381	    /// 摘要文件内容不符合格式约定。
382	    Malformed(PathBuf, DigestFileProblem),
383	}
384	
385	/// 摘要文件内容的具体格式问题，用于给出精确的错误原因。
386	enum DigestFileProblem {
387	    /// 空文件：连一个摘要字符都没有。
388	    Empty,
389	    /// 内容超过“64 个十六进制字符 + 单个 CRLF”的 66 字节上限：
390	    /// 多余字节可能是第二份摘要、文件名或任何附加内容，一律拒绝。
391	    TooLong,
392	    /// 去掉唯一允许的末尾换行后，摘要正文未通过库的严格十六进制解析。
393	    InvalidDigest(ParseDigestError),
394	}
395	
396	impl DigestFileProblem {
397	    /// 渲染为人类可读的具体格式原因（不含路径，路径由调用方添加）。
398	    fn description(&self) -> String {
399	        const RULE: &str = concat!(
400	            "the digest file must contain exactly one digest of 64 ASCII ",
401	            "hexadecimal characters, optionally followed by one LF or CRLF"
402	        );
403	        match self {
404	            DigestFileProblem::Empty => {
405	                format!("{RULE}, but the file is empty")
406	            }
407	            DigestFileProblem::TooLong => {
408	                format!("{RULE}, but the file contains extra bytes beyond that single line")
409	            }
410	            DigestFileProblem::InvalidDigest(ParseDigestError::InvalidLength(len)) => {
411	                format!(
412	                    "{RULE}; the digest text is {len} bytes long (before any trailing newline)"
413	                )
414	            }
415	            DigestFileProblem::InvalidDigest(ParseDigestError::InvalidHexChar(pos)) => {
416	                format!(
417	                    "{RULE}; the digest text contains a non-hexadecimal byte at offset {pos} \
418	                    (only 0-9, a-f and A-F are allowed)"
419	                )
420	            }
421	        }
422	    }
423	}
424	
425	/// 打开摘要文件、读取其（被严格限长的）全部内容并解析为摘要值。
426	///
427	/// 合法文件至多 66 字节：64 个十六进制字符，末尾可带一个 LF 或 CRLF。
428	/// 这里最多读入 67 字节——多出的第 67 字节是“内容超长”的确定性哨兵，
429	/// 因此内存占用恒定，也不必把可能很大的非法文件（例如误指向二进制或
430	/// 第二份摘要）整个读完就能判定格式错误。读取本身失败与内容格式不合法
431	/// 是两类不同的失败，分别映射到 [`DigestFileError`] 的不同变体。
432	fn load_expected_digest_file(path: &Path) -> Result<Sha256Digest, DigestFileError> {
433	    use std::io::Read as _;
434	
435	    let file = File::open(path).map_err(|err| {
436	        DigestFileError::Access(FileAccessError::open(FileRole::DigestFile, path, err))
437	    })?;
438	
439	    let mut content = Vec::with_capacity(67);
440	    file.take(67)
441	        .read_to_end(&mut content)
442	        .map_err(|err| {
443	            DigestFileError::Access(FileAccessError::read(
444	                FileRole::DigestFile,
445	                path,
446	                ReadError::Plain(err),
447	            ))
448	        })?;
449	
450	    parse_digest_file_content(&content)
451	        .map_err(|problem| DigestFileError::Malformed(path.to_path_buf(), problem))
452	}
